CAT_LABEL = [("ai", "AI Integration"), ("remote", "Remote Work"), ("saas", "SaaS"), ("enterprise", "Enterprise")]
def derive_label(cats):
    for k, v in CAT_LABEL:
        if k in cats: return v
    return "Full Stack"
SKILLS = {"enterprise": "Full-stack development", "apis": "API development", "automation": "System integration", "ai": "AI implementation", "saas": "Cloud", "analytics": "Database design", "remote": "Full-stack development"}

def build():
    out = []
    for lid, (layout, value) in UPGRADE.items():
        p = dict(legacy[lid])
        p["layout"] = layout; p["value"] = value
        p["features"] = p["functionality"][:3]
        p["label"] = derive_label(p["categories"])
        p["skills"] = list(dict.fromkeys([SKILLS[c] for c in p["categories"] if c in SKILLS] + ["Database design"]))[:4]
        p["arch"] = None; p["isnew"] = False
        out.append(p)
    out += NEW
    # interleave: professional first, then concept with AI/remote near the top of the concept list
    prof = [p for p in out if p["status"] == "professional"]
    conc = [p for p in out if p["status"] != "professional"]
    conc.sort(key=lambda p: (0 if p["label"] == "AI Integration" else 1 if p["label"] == "Remote Work" else 2))
    return prof + conc
PROJECTS = build()
